import Script from 'next/script';
import { redirect } from 'next/navigation';
import { createServerSupabase } from '@/lib/supabase/server';

/**
 * أداة «من سيربح المليون» — مولّد ألعاب ذكي بنظام رصيد.
 * يولّد 10 أسئلة، وسلّم المبالغ يتكيّف فآخر سؤال دائماً = المليون.
 */
export const dynamic = 'force-dynamic';

const GAME_CSS = "@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;500;700;800;900&display=swap');\n:root{\n  --sage:#7A9E7E; --sage-dark:#5C7F60; --gold:#C9A84C; --cream:#FAF8F3;\n  --ink:#2E3A2F; --royal:#0D1B4C; --royal2:#16276B; --game-gold:#F3C64B;\n}\n*{margin:0;padding:0;box-sizing:border-box;font-family:'Cairo',sans-serif}\nbody{background:var(--cream);color:var(--ink);min-height:100vh}\n\n/* ===== مولّد ===== */\n.gen-wrap{max-width:680px;margin:0 auto;padding:28px 18px 60px}\n.brand{text-align:center;margin-bottom:26px}\n.brand .seed{font-size:44px;line-height:1}\n.brand h1{font-size:26px;font-weight:900;color:var(--sage-dark);margin-top:6px}\n.brand p{color:#7d8a7e;font-size:14px;margin-top:4px}\n.badge{display:inline-block;background:var(--gold);color:#fff;font-size:11px;font-weight:700;padding:3px 12px;border-radius:20px;margin-top:8px}\n\n.card{background:#fff;border:1.5px solid #E8E4D8;border-radius:18px;padding:22px;margin-bottom:16px;box-shadow:0 2px 10px rgba(122,158,126,.07)}\n.card h2{font-size:16px;font-weight:800;color:var(--sage-dark);margin-bottom:12px;display:flex;align-items:center;gap:8px}\n.card h2 .num{background:var(--sage);color:#fff;width:26px;height:26px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;font-size:13px;flex-shrink:0}\n\n.tabs{display:flex;gap:8px;margin-bottom:14px}\n.tab{flex:1;padding:10px;border:1.5px solid #E8E4D8;border-radius:12px;background:#fff;font-weight:700;font-size:14px;cursor:pointer;color:#8a917f;transition:.2s}\n.tab.on{border-color:var(--sage);background:#F0F5F0;color:var(--sage-dark)}\n\n.drop{border:2px dashed #C8D4C9;border-radius:14px;padding:30px 16px;text-align:center;cursor:pointer;transition:.2s;background:#FBFCFA}\n.drop:hover,.drop.over{border-color:var(--sage);background:#F0F5F0}\n.drop .ic{font-size:34px}\n.drop p{font-size:14px;color:#6d7a6e;margin-top:8px;font-weight:500}\n.drop small{color:#a5aea0;font-size:12px}\n#fileInput{display:none}\n.thumbs{display:flex;flex-wrap:wrap;gap:10px;margin-top:14px}\n.thumb{position:relative;width:76px;height:96px;border-radius:10px;overflow:hidden;border:1.5px solid #E8E4D8}\n.thumb img{width:100%;height:100%;object-fit:cover}\n.thumb .x{position:absolute;top:4px;left:4px;background:rgba(0,0,0,.55);color:#fff;border:none;width:20px;height:20px;border-radius:50%;cursor:pointer;font-size:11px;line-height:1}\ntextarea{width:100%;min-height:170px;border:1.5px solid #E8E4D8;border-radius:14px;padding:14px;font-size:15px;resize:vertical;background:#FBFCFA;color:var(--ink)}\ntextarea:focus{outline:none;border-color:var(--sage)}\n\n.row{display:flex;gap:12px;flex-wrap:wrap}\n.field{flex:1;min-width:180px}\n.field label{display:block;font-size:13px;font-weight:700;color:#6d7a6e;margin-bottom:6px}\n.field input,.field select{width:100%;padding:11px 12px;border:1.5px solid #E8E4D8;border-radius:12px;font-size:14px;background:#FBFCFA;color:var(--ink)}\n.field input:focus,.field select:focus{outline:none;border-color:var(--sage)}\n\n.go{width:100%;padding:17px;border:none;border-radius:16px;background:linear-gradient(135deg,var(--sage),var(--sage-dark));color:#fff;font-size:19px;font-weight:900;cursor:pointer;box-shadow:0 6px 18px rgba(92,127,96,.35);transition:.2s;margin-top:4px}\n.go:hover{transform:translateY(-2px);box-shadow:0 9px 24px rgba(92,127,96,.45)}\n.go:disabled{opacity:.55;cursor:not-allowed;transform:none}\n\n.loading{text-align:center;padding:36px 10px;display:none}\n.loading.show{display:block}\n.spin{width:52px;height:52px;border:5px solid #E4EBE4;border-top-color:var(--sage);border-radius:50%;margin:0 auto 16px;animation:sp 1s linear infinite}\n@keyframes sp{to{transform:rotate(360deg)}}\n.loading .step{font-weight:700;color:var(--sage-dark);font-size:15px;min-height:22px}\n.err{display:none;background:#FBEEEC;border:1.5px solid #E7BBB3;color:#9C4536;border-radius:12px;padding:14px;font-size:14px;font-weight:500;margin-top:12px}\n.err.show{display:block}\n\n/* ===== معاينة الأسئلة ===== */\n.preview{display:none}\n.preview.show{display:block}\n.q-item{background:#FBFCFA;border:1.5px solid #E8E4D8;border-radius:12px;padding:14px;margin-bottom:10px}\n.q-item .qt{font-weight:800;font-size:14px;margin-bottom:6px}\n.q-item .lvl{display:inline-block;font-size:11px;background:#EFE7D2;color:#8a6d1f;border-radius:8px;padding:2px 8px;font-weight:700;margin-right:6px}\n.q-item .ans{font-size:13px;color:var(--sage-dark);font-weight:700}\n.play-btn{width:100%;padding:16px;border:none;border-radius:16px;background:linear-gradient(135deg,var(--gold),#B0913B);color:#fff;font-size:18px;font-weight:900;cursor:pointer;box-shadow:0 6px 18px rgba(201,168,76,.4);margin-top:8px}\n.regen{width:100%;padding:12px;border:1.5px solid #E8E4D8;border-radius:14px;background:#fff;color:#6d7a6e;font-weight:700;font-size:14px;cursor:pointer;margin-top:10px}\n\n/* ===== اللعبة ===== */\n#game{display:none;position:fixed;inset:0;z-index:100;overflow-y:auto;color:#fff;\n  background:\n    radial-gradient(circle 90px at 12% 18%,rgba(90,160,255,.20),transparent 70%),\n    radial-gradient(circle 60px at 88% 12%,rgba(140,190,255,.22),transparent 70%),\n    radial-gradient(circle 110px at 78% 42%,rgba(70,120,255,.16),transparent 70%),\n    radial-gradient(circle 70px at 8% 55%,rgba(120,180,255,.16),transparent 70%),\n    radial-gradient(circle 50px at 45% 15%,rgba(160,210,255,.14),transparent 70%),\n    radial-gradient(circle 80px at 60% 80%,rgba(80,130,255,.12),transparent 70%),\n    radial-gradient(ellipse 90% 55% at 50% -8%,#3A5BD9 0%,#1B2E7E 38%,#0B1550 68%,#050B2E 100%)}\n/* أعمدة إضاءة المسرح المتحركة */\n#game::before{content:'';position:fixed;inset:0;pointer-events:none;opacity:.8;\n  background:\n    conic-gradient(from 168deg at 18% -12%,transparent 0 47%,rgba(110,150,255,.22) 50%,transparent 53% 100%),\n    conic-gradient(from 192deg at 82% -12%,transparent 0 47%,rgba(110,150,255,.22) 50%,transparent 53% 100%),\n    conic-gradient(from 178deg at 42% -15%,transparent 0 48%,rgba(160,190,255,.16) 50%,transparent 52% 100%),\n    conic-gradient(from 182deg at 58% -15%,transparent 0 48%,rgba(160,190,255,.16) 50%,transparent 52% 100%);\n  animation:sweep 9s ease-in-out infinite alternate}\n@keyframes sweep{from{transform:translateX(-3%) }to{transform:translateX(3%)}}\n/* أرضية المسرح بمنظور + نقاط الجمهور */\n#game::after{content:'';position:fixed;left:0;right:0;bottom:0;height:38vh;pointer-events:none;\n  background:\n    radial-gradient(2px 2px at 12% 22%,rgba(255,225,140,.8),transparent 60%),\n    radial-gradient(2px 2px at 28% 48%,rgba(255,255,255,.5),transparent 60%),\n    radial-gradient(2px 2px at 44% 30%,rgba(255,225,140,.6),transparent 60%),\n    radial-gradient(2px 2px at 61% 52%,rgba(255,255,255,.45),transparent 60%),\n    radial-gradient(2px 2px at 75% 28%,rgba(255,225,140,.7),transparent 60%),\n    radial-gradient(2px 2px at 90% 45%,rgba(255,255,255,.5),transparent 60%),\n    radial-gradient(2px 2px at 8% 68%,rgba(255,225,140,.5),transparent 60%),\n    radial-gradient(2px 2px at 52% 75%,rgba(255,255,255,.4),transparent 60%),\n    radial-gradient(2px 2px at 83% 70%,rgba(255,225,140,.55),transparent 60%),\n    repeating-linear-gradient(90deg,transparent 0 46px,rgba(90,130,255,.10) 46px 48px),\n    linear-gradient(180deg,transparent 0%,rgba(20,35,110,.55) 40%,rgba(8,15,55,.9) 100%)}\n#game.show{display:block}\n.g-inner{max-width:900px;margin:0 auto;padding:22px 16px 50px;min-height:100vh;display:flex;flex-direction:column;position:relative}\n.g-close{position:absolute;top:10px;left:10px;background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.2);color:#fff;width:36px;height:36px;border-radius:50%;font-size:16px;cursor:pointer;z-index:5}\n\n/* سداسيات ثلاثية الأبعاد */\n.hex{clip-path:polygon(26px 0,calc(100% - 26px) 0,100% 50%,calc(100% - 26px) 100%,26px 100%,0 50%)}\n.hexline{position:relative;background:linear-gradient(180deg,#FFE9A3 0%,#F3C64B 28%,#B8860B 62%,#8A6508 100%);padding:3px;\n  filter:drop-shadow(0 7px 10px rgba(0,0,0,.5)) drop-shadow(0 0 12px rgba(243,198,75,.3))}\n.hexline>.hexin{background:linear-gradient(180deg,#25379E 0%,#131F6B 45%,#0A123F 100%);position:relative}\n.hexline>.hexin::before{content:'';position:absolute;left:8%;right:8%;top:0;height:46%;pointer-events:none;\n  background:linear-gradient(180deg,rgba(255,255,255,.22),transparent);border-radius:0 0 50% 50%}\n\n.q-box{margin-bottom:18px;position:relative}\n.q-label{display:flex;justify-content:center;margin-bottom:-14px;position:relative;z-index:2}\n.q-label span{background:linear-gradient(180deg,#FFE9A3,#F3C64B 45%,#B8860B);color:#2A1E00;font-weight:900;font-size:14px;padding:7px 26px;clip-path:polygon(14px 0,calc(100% - 14px) 0,100% 50%,calc(100% - 14px) 100%,14px 100%,0 50%);box-shadow:0 3px 8px rgba(0,0,0,.4)}\n.q-box .hexin{padding:26px 40px 20px;font-size:19px;font-weight:800;text-align:center;line-height:1.8;text-shadow:0 2px 4px rgba(0,0,0,.5)}\n.opts{display:grid;grid-template-columns:1fr 1fr;gap:14px 22px;perspective:800px;padding-right:14px}\n@media(max-width:560px){.opts{grid-template-columns:1fr}}\n.opt{border:none;background:none;padding:0;cursor:pointer;text-align:right;transition:transform .15s;position:relative}\n.opt .hexin{display:flex;align-items:center;padding:14px 40px 14px 20px;font-size:16px;font-weight:800;color:#fff;transition:.15s;text-shadow:0 2px 3px rgba(0,0,0,.55);justify-content:space-between;gap:8px}\n.opt .n{position:absolute;right:-13px;top:50%;transform:translateY(-50%);z-index:3;\n  width:40px;height:40px;background:linear-gradient(180deg,#FFE9A3,#F3C64B 45%,#C68A10);color:#2A1E00;display:flex;align-items:center;justify-content:center;font-weight:900;font-size:17px;\n  clip-path:polygon(50% 0,100% 25%,100% 75%,50% 100%,0 75%,0 25%);\n  filter:drop-shadow(0 3px 4px rgba(0,0,0,.45));text-shadow:none}\n.opt .oi{font-size:20px;flex-shrink:0}\n.opt:hover:not(:disabled){transform:translateY(-3px) scale(1.015)}\n.opt:hover:not(:disabled) .hexin{background:linear-gradient(180deg,#2F44BE 0%,#1A2A88 45%,#101B5E 100%)}\n.opt:active:not(:disabled){transform:translateY(1px) scale(.99)}\n.opt:disabled{cursor:default}\n\n/* الشعار */\n.g-logo{border-radius:50%;position:relative;\n  background:\n    repeating-conic-gradient(from 0deg,rgba(150,190,255,.28) 0 4deg,transparent 4deg 12deg),\n    radial-gradient(circle at 50% 42%,#3B5AE0 0%,#16247E 55%,#0A1250 100%);\n  border:4px solid #D9A21B;outline:2.5px solid #F8DE8B;outline-offset:-9px;\n  box-shadow:0 0 34px rgba(243,198,75,.6),inset 0 0 26px rgba(60,100,230,.6);\n  display:flex;align-items:center;justify-content:center;text-align:center}\n.g-logo b{font-size:17px;font-weight:900;color:#fff;text-shadow:0 0 12px rgba(243,198,75,.9),0 2px 3px rgba(0,0,0,.6);line-height:1.4}\n.g-logo b span{display:block;font-size:24px;color:var(--game-gold)}\n.g-start .g-logo{width:130px;height:130px;margin:0 auto 14px}\n.ladder-col{display:flex;flex-direction:column}\n@media(max-width:700px){.ladder-col{order:-1;flex-direction:row;align-items:center;gap:12px}.ladder-col .ladder{flex:1}}\n\n.g-start{text-align:center;margin:auto 0;padding:30px 0}\n.g-title{display:inline-block;margin-bottom:6px}\n.g-title .hexin{padding:12px 44px;font-size:26px;font-weight:900;color:var(--game-gold);text-shadow:0 0 16px rgba(243,198,75,.5)}\n.g-start h2{font-size:15px;font-weight:700;color:#B9C4EF;margin:12px 0 24px}\n.g-start input{width:min(320px,90%);padding:13px;border-radius:14px;border:2px solid rgba(243,198,75,.55);background:rgba(255,255,255,.08);color:#fff;font-size:16px;text-align:center;margin-bottom:22px}\n.g-start input::placeholder{color:#8FA0D8}\n.g-startbtn{display:block;margin:0 auto;padding:15px 52px;border:none;border-radius:50px;background:linear-gradient(135deg,var(--game-gold),#D9A21B);color:#3A2A00;font-size:20px;font-weight:900;cursor:pointer;box-shadow:0 0 30px rgba(243,198,75,.5);animation:pulse 1.8s infinite}\n@keyframes pulse{50%{box-shadow:0 0 46px rgba(243,198,75,.85)}}\n.g-brand{margin-top:auto;text-align:center;color:#7286C9;font-size:12px;padding-top:24px}\n\n/* تخطيط اللعب: أسئلة + سلم المبالغ */\n.play-grid{display:grid;grid-template-columns:1fr 210px;gap:18px;align-items:start}\n@media(max-width:700px){.play-grid{grid-template-columns:1fr}}\n.hud{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:14px;flex-wrap:wrap}\n.hud .pill{background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.18);border-radius:30px;padding:7px 16px;font-weight:800;font-size:14px}\n#timer{border-color:rgba(243,198,75,.45)}\n#timer.hot{color:#FF7B6B;animation:blink .5s infinite}\n@keyframes blink{50%{opacity:.4}}\n.prog{height:8px;background:rgba(255,255,255,.12);border-radius:10px;overflow:hidden;margin-bottom:18px}\n.prog i{display:block;height:100%;background:linear-gradient(90deg,var(--game-gold),#F8DE8B);border-radius:10px;transition:width .5s}\n\n.q-box{margin-bottom:18px}\n.opt.correct .hexin{background:linear-gradient(180deg,#1F7A45,#125230)!important;box-shadow:inset 0 0 18px rgba(75,217,138,.4)}\n.opt.correct .hexline{background:linear-gradient(135deg,#4BD98A,#1F7A45)}\n.opt.wrong .hexin{background:linear-gradient(180deg,#8C2B25,#5E1B17)!important}\n.opt.wrong{animation:shake .4s}\n@keyframes shake{25%{transform:translateX(6px)}75%{transform:translateX(-6px)}}\n.opt.dim{opacity:.25;pointer-events:none}\n\n/* سلم المبالغ */\n.ladder{background:linear-gradient(180deg,#0E1A5E,#081040);border:2.5px solid #D9A21B;border-radius:16px;padding:0 0 12px;box-shadow:0 0 22px rgba(243,198,75,.3);overflow:hidden}\n.ladder h3{text-align:center;font-size:15px;font-weight:900;color:#2A1E00;background:linear-gradient(180deg,#FFE9A3,#F3C64B 50%,#C68A10);padding:9px;margin-bottom:8px}\n.lrow{display:flex;align-items:center;gap:8px;padding:4px 12px;font-size:13.5px;font-weight:800;color:#E7EBFA}\n.lrow .li{color:var(--game-gold);width:20px;text-align:center}\n.lrow .lp{flex:1}\n.lrow .lc{font-size:12px}\n.lrow.won{color:#F8DE8B}\n.lrow.cur{background:linear-gradient(90deg,#F08A1D,#D96E0A);color:#fff;box-shadow:0 0 14px rgba(240,138,29,.65);margin:0 5px;border-radius:8px;padding:4px 7px}\n.ladder .helps{display:flex;gap:8px;justify-content:center;margin-top:10px;padding-top:10px;border-top:1.5px solid rgba(243,198,75,.4)}\n.ladder .help{width:44px;height:44px;padding:0;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:13px}\n.helps{display:flex;gap:10px;justify-content:center;margin-top:16px}\n.help{background:rgba(255,255,255,.1);border:2px solid #D9A21B;color:#fff;border-radius:30px;padding:9px 16px;font-weight:800;font-size:13px;cursor:pointer;box-shadow:0 0 10px rgba(243,198,75,.3)}\n.help:disabled{opacity:.3;cursor:not-allowed;box-shadow:none}\n\n.fb{display:none;background:rgba(10,18,63,.92);border:2px solid rgba(243,198,75,.5);border-radius:18px;padding:20px;margin-top:18px;text-align:center}\n.fb.show{display:block}\n.fb .h{font-size:20px;font-weight:900;margin-bottom:8px}\n.fb .h.ok{color:#4BD98A}.fb .h.no{color:#FF7B6B}\n.fb .ex{font-size:15px;color:#D5DCF5;line-height:1.8}\n.fb button{margin-top:14px;padding:12px 40px;border:none;border-radius:40px;background:var(--game-gold);color:#3A2A00;font-weight:900;font-size:16px;cursor:pointer}\n.g-end{text-align:center;margin:auto 0;padding:30px 0}\n.g-end .medal{font-size:70px}\n.g-end h1{font-size:26px;font-weight:900;color:var(--game-gold);margin:10px 0}\n.g-end .stats{display:flex;justify-content:center;gap:14px;flex-wrap:wrap;margin:20px 0}\n.g-end .st{background:rgba(255,255,255,.08);border:1.5px solid rgba(243,198,75,.4);border-radius:14px;padding:14px 22px;min-width:110px}\n.g-end .st b{display:block;font-size:24px;color:var(--game-gold)}\n.g-end .st span{font-size:13px;color:#B9C4EF}\n.confetti{position:fixed;top:-10px;width:10px;height:14px;z-index:200;pointer-events:none;animation:fall linear forwards}\n@keyframes fall{to{transform:translateY(105vh) rotate(600deg)}}\n\n/* ===== وضع كتابة الأسئلة يدويًا ===== */\n.man-note{background:#FBF3DD;border:1.5px solid #EADFB8;color:#8a6d1f;font-size:13px;font-weight:700;padding:10px 12px;border-radius:12px;margin-bottom:12px;line-height:1.7}\n.man-form{display:flex;flex-direction:column;gap:9px}\n.man-in{width:100%;padding:11px 13px;border:1.5px solid #E8E4D8;border-radius:12px;font-size:14px;background:#FBFCFA;color:#2E3A2F}\n.man-in:focus{outline:none;border-color:#7A9E7E}\n.man-opt{display:flex;align-items:center;gap:9px}\n.man-opt input[type=radio]{width:22px;height:22px;flex-shrink:0;accent-color:#5C7F60;cursor:pointer}\n.man-opt .man-in{flex:1}\n.man-hint{font-size:12.5px;color:#a5aea0}\n.man-add{background:#F0F5F0;border:1.5px solid #DDE8DD;color:#5C7F60;font-weight:800;font-size:14px;padding:12px;border-radius:12px;cursor:pointer;transition:.18s}\n.man-add:hover{background:#E7F0E8}\n.man-list{margin-top:12px;display:flex;flex-direction:column;gap:8px}\n.man-q{background:#FBFCFA;border:1.5px solid #E8E4D8;border-radius:12px;padding:10px 12px;display:flex;gap:8px;align-items:flex-start}\n.man-q .mqt{flex:1;font-size:13.5px;font-weight:700;color:#2E3A2F}\n.man-q .mqa{font-size:12.5px;color:#5C7F60;font-weight:700;margin-top:3px}\n.man-q .mdel{background:none;border:none;color:#c9908a;font-size:15px;cursor:pointer;flex-shrink:0}\n.man-use{width:100%;padding:15px;border:none;border-radius:14px;background:linear-gradient(135deg,#F3C64B,#B0913B);color:#fff;font-size:16px;font-weight:900;cursor:pointer;margin-top:12px}\n\n.free-banner{display:none;margin-top:10px;background:linear-gradient(180deg,#FFF3D0,#FBE3A6);color:#7A5A12;\n  font-weight:900;font-size:14px;padding:10px 18px;border-radius:16px;border:1.6px solid #EAD08A;\n  box-shadow:0 4px 12px rgba(217,162,22,.22);animation:fbpop .5s ease}\n@keyframes fbpop{from{transform:scale(.9);opacity:0}to{transform:scale(1);opacity:1}}\n\n/* ===== شارة الرصيد + الشراء ===== */\n.cbadge{display:inline-block;margin-top:10px;background:#EAF3EC;color:#3E6B45;font-weight:800;font-size:13px;padding:6px 16px;border-radius:20px;border:1.5px solid #CFE3D2}\n.cbadge.empty{background:#FBEEEC;color:#9C4536;border-color:#E7BBB3}\n.cbadge.admin{background:#FBF3DD;color:#8a6d1f;border-color:#EADFB8}\n.buy-link{display:block;margin:10px auto 0;background:none;border:none;color:#5C7F60;font-weight:800;font-size:13px;cursor:pointer;text-decoration:underline}\n.buy-ov{position:fixed;inset:0;z-index:300;background:rgba(20,30,25,.55);backdrop-filter:blur(3px);display:none;align-items:center;justify-content:center;padding:20px}\n.buy-ov.show{display:flex}\n.buy-card{background:#fff;border-radius:22px;max-width:400px;width:100%;padding:28px 24px;text-align:center;position:relative;box-shadow:0 20px 60px rgba(0,0,0,.3);animation:pop .25s ease}\n@keyframes pop{from{transform:scale(.9);opacity:0}to{transform:scale(1);opacity:1}}\n.buy-x{position:absolute;top:14px;left:14px;background:#F0F1EC;border:none;width:30px;height:30px;border-radius:50%;cursor:pointer;font-size:13px;color:#6d7a6e}\n.buy-seed{font-size:40px}\n.buy-card h3{font-size:20px;font-weight:900;color:var(--sage-dark);margin:6px 0 8px}\n.buy-card p{color:#7d8a7e;font-size:14px;line-height:1.7}\n.buy-opts{display:flex;gap:12px;margin:18px 0 6px}\n.buy-opt{flex:1;position:relative;background:#FBFCFA;border:2px solid #E8E4D8;border-radius:16px;padding:16px 10px;cursor:pointer;transition:.18s;display:flex;flex-direction:column;align-items:center;gap:3px}\n.buy-opt:hover{border-color:var(--sage);transform:translateY(-2px)}\n.buy-opt b{font-size:15px;color:var(--ink);font-weight:800}\n.buy-opt .pr{font-size:19px;font-weight:900;color:var(--sage-dark)}\n.buy-opt small{font-size:11px;color:#a5aea0}\n.buy-opt.best{border-color:var(--gold);background:#FFFDF6}\n.buy-opt.best .tag{position:absolute;top:-11px;right:50%;transform:translateX(50%);background:var(--gold);color:#fff;font-size:10px;font-weight:800;padding:2px 10px;border-radius:20px;white-space:nowrap}\n.buy-note{font-size:12px;color:#a5aea0;margin-top:14px}\n\n.q-box .hexin{ font-size:28px !important; padding:32px 48px 26px !important; line-height:1.75 !important; }\n.q-label span{ font-size:17px !important; padding:8px 30px !important; }\n/* بطاقات الإجابات: بار كامل بعرض ثابت (block) عشان تبين واضحة في كل المتصفحات */\n.opt{ display:block !important; }\n.opt .hexline{ display:block !important; width:100% !important; }\n.opt .hexin{ display:flex !important; align-items:center !important; min-height:64px !important; font-size:23px !important; padding:20px 52px 20px 22px !important; }\n.opt .n{ width:48px !important; height:48px !important; font-size:22px !important; right:-15px !important; }\n.opt .oi{ font-size:24px !important; }\n@media(max-width:560px){\n  .q-box .hexin{ font-size:22px !important; padding:24px 30px 20px !important; }\n  .opt .hexin{ font-size:20px !important; min-height:56px !important; padding:16px 44px 16px 18px !important; }\n  .opt .n{ width:42px !important; height:42px !important; font-size:19px !important; }\n}\n\n/* الأعمدة الضوئية تتمايل بوضوح */\n#game::before{ animation:mfxsweep 8s ease-in-out infinite alternate !important; }\n@keyframes mfxsweep{ from{transform:translateX(-4%) rotate(-1.3deg)} to{transform:translateX(4%) rotate(1.3deg)} }\n/* طبقة خلفية متحركة: أشعة تدور + جسيمات ذهبية تطفو */\n.mfx{ position:fixed; inset:0; pointer-events:none; z-index:0; overflow:hidden; }\n.mfx::before{ content:''; position:absolute; left:50%; top:50%; width:230vmax; height:230vmax; margin-left:-115vmax; margin-top:-115vmax;\n  background:repeating-conic-gradient(from 0deg, rgba(130,170,255,.06) 0deg 5deg, transparent 5deg 13deg);\n  animation:mfxspin 70s linear infinite; }\n@keyframes mfxspin{ to{ transform:rotate(360deg) } }\n.mfx::after{ content:''; position:absolute; inset:0; opacity:.9;\n  background-image:\n    radial-gradient(1.6px 1.6px at 20px 30px, rgba(255,225,140,.75), transparent 60%),\n    radial-gradient(1.4px 1.4px at 80px 90px, rgba(255,255,255,.5), transparent 60%),\n    radial-gradient(1.8px 1.8px at 150px 50px, rgba(255,225,140,.6), transparent 60%);\n  background-size:180px 200px, 260px 300px, 340px 380px;\n  animation:mfxdrift 26s linear infinite; }\n@keyframes mfxdrift{ to{ background-position:0 -800px, 0 -1200px, 0 -1600px } }\n/* المحتوى فوق الخلفية دائمًا */\n.g-inner{ z-index:1; }\n/* احترام تفضيل تقليل الحركة */\n@media(prefers-reduced-motion:reduce){ #game::before,.mfx::before,.mfx::after{ animation:none !important } }\n\n/* ملء الشاشة عموديًا: توسيط منطقة اللعب (السؤال + الخيارات + قائمة المبالغ) فيختفي الفراغ السفلي */\n.play-grid{ flex:1 1 auto !important; align-items:center !important; align-content:center !important; }\n.opts{ gap:22px 28px !important; }\n.q-box{ margin-bottom:24px !important; }\n.ladder-col{ justify-content:center !important; }\n@media(max-width:700px){ .play-grid{ align-content:start !important; } }\n\n/* ملء الشاشة عرضًا (كان محصورًا 900px) */\n.g-inner{ max-width:1650px !important; width:96vw !important; padding:18px 30px 28px !important; }\n.play-grid{ grid-template-columns:1fr 270px !important; gap:16px 30px !important; }\n/* شريط العنوان العلوي مثل الصورة */\n.q-header{ text-align:center; margin-bottom:12px; }\n.q-title{ display:inline-block; background:linear-gradient(180deg,#25379E,#131F6B); border:2.5px solid #D9A21B; border-radius:14px; padding:11px 46px; box-shadow:0 0 22px rgba(243,198,75,.3); }\n.q-title span{ font-size:27px; font-weight:900; color:var(--game-gold); text-shadow:0 0 14px rgba(243,198,75,.45); }\n.q-sub2{ margin-top:8px; font-size:15px; font-weight:800; color:#CBD6FF; letter-spacing:.5px; }\n@media(max-width:700px){\n  .g-inner{ width:100vw !important; padding:12px 12px 22px !important; }\n  .play-grid{ grid-template-columns:1fr !important; }\n  .q-title span{ font-size:20px }\n  .q-title{ padding:9px 26px }\n}\n\n.mg-home{ display:inline-flex; align-items:center; gap:6px; color:var(--sage-dark); font-weight:800; font-size:13.5px; text-decoration:none; background:#F0F5F0; border:1.5px solid #DDE8DD; border-radius:12px; padding:9px 16px; margin-bottom:16px; transition:.18s; }\n.mg-home:hover{ background:#E7F0E8; border-color:var(--sage); }\n.g-home{ position:absolute; top:10px; right:10px; background:rgba(255,255,255,.12); border:1px solid rgba(255,255,255,.2); color:#fff; width:38px; height:38px; border-radius:50%; font-size:17px; display:flex; align-items:center; justify-content:center; z-index:6; text-decoration:none; transition:.18s; }\n.g-home:hover{ background:rgba(255,255,255,.24); }\n";
const GAME_BODY = "<!-- ============ المولّد ============ -->\n<div class=\"gen-wrap\" id=\"genWrap\">\n  <a href=\"/\" class=\"mg-home\">← رجوع لمنصة غراس</a>\n  <div class=\"brand\">\n    <div class=\"seed\">🌱</div>\n    <h1>مولّد الألعاب الذكي</h1>\n    <p>ارفع الدرس… واستلم اللعبة جاهزة</p>\n    <span class=\"badge\">أداة غراس المعلم</span>\n    <div id=\"creditBadge\" class=\"cbadge\"></div>\n    <button class=\"buy-link\" onclick=\"showBuy()\">＋ شراء ألعاب</button>\n  </div>\n\n  <div class=\"card\">\n    <h2><span class=\"num\">١</span> محتوى الدرس</h2>\n    <div class=\"tabs\">\n      <button class=\"tab on\" id=\"tabImg\" onclick=\"switchTab('img')\">📷 صور الدرس</button>\n      <button class=\"tab\" id=\"tabTxt\" onclick=\"switchTab('txt')\">📝 نص الدرس</button>\n      <button class=\"tab\" id=\"tabMan\" onclick=\"switchTab('man')\">✍️ اكتب أسئلتك</button>\n    </div>\n    <div id=\"paneImg\">\n      <label class=\"drop\" id=\"drop\" for=\"fileInput\" style=\"display:block\">\n        <div class=\"ic\">📄</div>\n        <p>اضغط هنا لرفع صور صفحات الدرس</p>\n        <small>أو صوّرها بالكاميرا مباشرة — حتى ٥ صور</small>\n      </label>\n      <input type=\"file\" id=\"fileInput\" accept=\"image/*\" multiple>\n      <div class=\"thumbs\" id=\"thumbs\"></div>\n    </div>\n    <div id=\"paneTxt\" style=\"display:none\">\n      <textarea id=\"lessonText\" placeholder=\"الصق نص الدرس هنا…\"></textarea>\n    </div>\n    <div id=\"paneMan\" style=\"display:none\">\n      <div class=\"man-note\">✍️ اكتب أسئلتك كما تريد — تُستخدم <b>حرفيًا بدون أي تعديل</b> من الذكاء.</div>\n      <div class=\"man-form\">\n        <input id=\"mq\" class=\"man-in\" placeholder=\"اكتب نص السؤال…\">\n        <div class=\"man-opt\"><input type=\"radio\" name=\"mcorrect\" value=\"0\" checked title=\"الصحيحة\"><input id=\"mo0\" class=\"man-in\" placeholder=\"الخيار الأول\"></div>\n        <div class=\"man-opt\"><input type=\"radio\" name=\"mcorrect\" value=\"1\" title=\"الصحيحة\"><input id=\"mo1\" class=\"man-in\" placeholder=\"الخيار الثاني\"></div>\n        <div class=\"man-opt\"><input type=\"radio\" name=\"mcorrect\" value=\"2\" title=\"الصحيحة\"><input id=\"mo2\" class=\"man-in\" placeholder=\"الخيار الثالث\"></div>\n        <div class=\"man-opt\"><input type=\"radio\" name=\"mcorrect\" value=\"3\" title=\"الصحيحة\"><input id=\"mo3\" class=\"man-in\" placeholder=\"الخيار الرابع\"></div>\n        <div class=\"man-hint\">حدّد الدائرة أمام الإجابة الصحيحة 👆 ثم أضف السؤال</div>\n        <button class=\"man-add\" onclick=\"addManualQ()\">➕ أضف السؤال</button>\n      </div>\n      <div id=\"manList\" class=\"man-list\"></div>\n      <button class=\"man-use\" id=\"manUseBtn\" onclick=\"useManual()\" style=\"display:none\">▶️ استخدم أسئلتي</button>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <h2><span class=\"num\">٢</span> إعدادات اللعبة</h2>\n    <div class=\"row\">\n      <div class=\"field\">\n        <label>اسم الدرس (اختياري)</label>\n        <input id=\"lessonName\" placeholder=\"مثال: غزوة بدر\">\n      </div>\n      <div class=\"field\">\n        <label>الصف</label>\n        <select id=\"gradeSel\">\n          <option value=\"الأول\">الأول</option><option value=\"الثاني\">الثاني</option>\n          <option value=\"الثالث\">الثالث</option><option value=\"الرابع\">الرابع</option>\n          <option value=\"الخامس\" selected>الخامس</option><option value=\"السادس\">السادس</option>\n          <option value=\"السابع\">السابع</option><option value=\"الثامن\">الثامن</option><option value=\"التاسع\">التاسع</option>\n        </select>\n      </div>\n      <div class=\"field\">\n        <label>الفئة</label>\n        <select id=\"genderSel\">\n          <option value=\"بنات\" selected>بنات</option>\n          <option value=\"بنين\">بنين</option>\n        </select>\n      </div>\n    </div>\n  </div>\n\n  <button class=\"go\" id=\"goBtn\" onclick=\"generate()\">✨ إنشاء اللعبة</button>\n  <button class=\"regen\" style=\"margin-top:10px\" onclick=\"demoPlay()\">👀 معاينة شكل اللعبة (أسئلة تجريبية)</button>\n\n  <div class=\"loading\" id=\"loading\">\n    <div class=\"spin\"></div>\n    <div class=\"step\" id=\"stepText\">جارٍ قراءة الدرس…</div>\n  </div>\n  <div class=\"err\" id=\"errBox\"></div>\n\n  <div class=\"card preview\" id=\"preview\">\n    <h2><span class=\"num\">٣</span> الأسئلة المولّدة <span id=\"qCount\" style=\"color:#a5aea0;font-weight:500;font-size:13px\"></span></h2>\n    <div id=\"qList\"></div>\n    <button class=\"play-btn\" onclick=\"openGame()\">🏆 تشغيل اللعبة</button>\n    <button class=\"regen\" onclick=\"generate()\">🔄 إعادة توليد الأسئلة</button>\n  </div>\n</div>\n\n<!-- ============ اللعبة ============ -->\n<div id=\"game\">\n  <div class=\"mfx\" aria-hidden=\"true\"></div>\n  <button class=\"g-close\" onclick=\"closeGame()\">✕</button>\n  <a href=\"/\" class=\"g-home\" aria-label=\"الرئيسية\" title=\"رجوع للمنصة\">🏠</a>\n  <div class=\"g-inner\" id=\"gInner\"></div>\n</div>";
const GAME_JS = "/* ---------- الحالة ---------- */\nlet images=[], questions=[], gi=0, correct=0, playerName='', timerInt=null, timeLeft=30;\nlet COMMITTED=false, DEMO=false;\nconst IS_ADMIN=!!(window.__IS_ADMIN);\nlet CREDITS=(typeof window.__GAME_CREDITS==='number')?window.__GAME_CREDITS:0;\nlet helpsUsed={fifty:false,teacher:false,audience:false};\nlet LESSON='';\nconst FULL_LADDER=['٢٬٠٠٠','٤٬٠٠٠','٨٬٠٠٠','١٦٬٠٠٠','٣٢٬٠٠٠','٦٤٬٠٠٠','١٢٥٬٠٠٠','٢٥٠٬٠٠٠','٥٠٠٬٠٠٠','١٬٠٠٠٬٠٠٠'];\nfunction getLadder(n){ n=Math.max(1,Math.min(FULL_LADDER.length,n)); return FULL_LADDER.slice(FULL_LADDER.length-n); }\nlet LADDER=FULL_LADDER.slice();\nconst AR=n=>String(n).replace(/[0-9]/g,d=>'٠١٢٣٤٥٦٧٨٩'[d]);\n\n/* ---------- التبويبات والصور ---------- */\nfunction switchTab(t){\n  document.getElementById('tabImg').classList.toggle('on',t==='img');\n  document.getElementById('tabTxt').classList.toggle('on',t==='txt');\n  document.getElementById('tabMan').classList.toggle('on',t==='man');\n  document.getElementById('paneImg').style.display=t==='img'?'':'none';\n  document.getElementById('paneTxt').style.display=t==='txt'?'':'none';\n  document.getElementById('paneMan').style.display=t==='man'?'':'none';\n  document.getElementById('goBtn').style.display=t==='man'?'none':'';\n}\ndocument.getElementById('fileInput').addEventListener('change',e=>addFiles(e.target.files));\nconst drop=document.getElementById('drop');\ndrop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('over')});\ndrop.addEventListener('dragleave',()=>drop.classList.remove('over'));\ndrop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('over');addFiles(e.dataTransfer.files)});\n\nfunction addFiles(files){\n  [...files].slice(0,5-images.length).forEach(f=>{\n    if(!f.type.startsWith('image/'))return;\n    const r=new FileReader();\n    r.onerror=()=>showErr('تعذّرت قراءة الصورة — جرّب صورة ثانية');\n    r.onload=()=>{\n      const img=new Image();\n      img.onload=()=>{\n        try{\n          const MAX=900;\n          let w=img.width,h=img.height;\n          if(Math.max(w,h)>MAX){const s=MAX/Math.max(w,h);w=Math.round(w*s);h=Math.round(h*s)}\n          const cv=document.createElement('canvas');cv.width=w;cv.height=h;\n          cv.getContext('2d').drawImage(img,0,0,w,h);\n          const url=cv.toDataURL('image/jpeg',0.65);\n          images.push({data:url.split(',')[1],type:'image/jpeg',url});\n        }catch(e){\n          images.push({data:r.result.split(',')[1],type:f.type,url:r.result});\n        }\n        renderThumbs();\n      };\n      img.onerror=()=>{\n        images.push({data:r.result.split(',')[1],type:f.type,url:r.result});\n        renderThumbs();\n      };\n      img.src=r.result;\n    };\n    r.readAsDataURL(f);\n  });\n  document.getElementById('fileInput').value='';\n}\nfunction renderThumbs(){\n  document.getElementById('thumbs').innerHTML=images.map((im,i)=>\n    `<div class=\"thumb\"><img src=\"${im.url}\"><button class=\"x\" onclick=\"images.splice(${i},1);renderThumbs()\">✕</button></div>`).join('');\n}\n\n/* ---------- التوليد ---------- */\nconst STEPS=['جارٍ قراءة صفحات الدرس… 📖','جارٍ استخراج المفاهيم والحقائق… 🔍','جارٍ بناء الأسئلة حسب مستويات بلوم… 🧠','جارٍ تجهيز اللعبة… 🎮'];\nasync function generate(){\n  DEMO=false;COMMITTED=false;MANUAL=false;\n  if(!IS_ADMIN && CREDITS<=0){ showBuy(); return; }\n  const text=document.getElementById('lessonText').value.trim();\n  if(images.length===0 && !text){showErr('ارفع صور الدرس أو الصق النص أولاً 🌱');return}\n  hideErr();\n  document.getElementById('preview').classList.remove('show');\n  document.getElementById('goBtn').disabled=true;\n  document.getElementById('loading').classList.add('show');\n  let si=0;const st=document.getElementById('stepText');st.textContent=STEPS[0];\n  const stepInt=setInterval(()=>{si=(si+1)%STEPS.length;st.textContent=STEPS[si]},3500);\n\n  const grade=document.getElementById('gradeSel').value;\n  const gender=document.getElementById('genderSel').value;\n  const lname=document.getElementById('lessonName').value.trim();\n  const genderNote=gender==='بنات'?'خاطب الطالبات بصيغة المؤنث':'خاطب الطلاب بصيغة المذكر';\n\n  const basePrompt=(part)=>`أنت خبير مناهج كويتي. أمامك محتوى درس للصف ${grade}${lname?` بعنوان \"${lname}\"`:''}.\nولّد 10 أسئلة اختيار من متعدد متدرّجة من السهل (تذكّر وفهم) إلى الصعب (تطبيق وتحليل وتقويم)، مستخرجة من محتوى الدرس فقط.\nشروط: ${genderNote}. 4 خيارات، إجابة واحدة صحيحة، مشتتات خاطئة قطعاً. الشرح سطر واحد قصير جداً. الآيات والأحاديث تُنقل بدقة.\nأجب بـ JSON مضغوط فقط بلا أسطر زائدة وبلا markdown:\n{\"lesson\":\"اسم الدرس\",\"questions\":[{\"q\":\"..\",\"options\":[\"..\",\"..\",\"..\",\"..\"],\"correct\":0,\"level\":\"تذكر\",\"explain\":\"..\"}]}\n${text?`\\nنص الدرس:\\n${text}`:''}`;\n\n  async function callAPI(part,imgSet){\n    const imgs=imgSet||images;\n    const content=[...imgs.map(im=>({type:'image',source:{type:'base64',media_type:im.type,data:im.data}})),{type:'text',text:basePrompt(part)}];\n    const body=JSON.stringify({max_tokens:2500,messages:[{role:'user',content}]});\n    const kb=Math.round(body.length/1024);\n    const res=await fetch('/api/game-ai',{\n      method:'POST',headers:{'Content-Type':'application/json'},body\n    });\n    const data=await res.json();\n    if(data.error)throw new Error((data.error.message||'خطأ في الخدمة')+` [حجم الطلب: ${kb}KB]`);\n    const raw=(data.content||[]).filter(b=>b.type==='text').map(b=>b.text).join('\\n');\n    const clean=raw.replace(/```json|```/g,'').trim();\n    const slice=clean.slice(clean.indexOf('{'),clean.lastIndexOf('}')+1);\n    let parsed;\n    try{parsed=JSON.parse(slice)}\n    catch(_){\n      const cut=slice.lastIndexOf('},');\n      if(cut>0)parsed=JSON.parse(slice.slice(0,cut+1)+']}');\n      else throw new Error('تعذّر قراءة النتيجة');\n    }\n    return parsed;\n  }\n\n  async function tryGenerate(part){\n    try{return await callAPI(part)}\n    catch(e){\n      if(images.length>1){\n        document.getElementById('stepText').textContent='جارٍ المحاولة بصورة واحدة… 🔄';\n        return await callAPI(part,[images[0]]);\n      }\n      throw e;\n    }\n  }\n\n  try{\n    const p1=await tryGenerate(1);\n    let all=[...(p1.questions||[])];\n    let lessonTitle=p1.lesson||'';\n    // إكمال حتى 10 أسئلة (بلا تكرار) إن نقصت الدفعة الأولى\n    let tries=0;\n    while(all.length<10 && tries<3){\n      tries++;\n      try{\n        const pt=await tryGenerate(2);\n        const seen=new Set(all.map(q=>q.q));\n        (pt.questions||[]).forEach(q=>{ if(q&&q.q&&!seen.has(q.q)){ all.push(q); seen.add(q.q); } });\n        lessonTitle=lessonTitle||pt.lesson||'';\n      }catch(_){ break; }\n    }\n    questions=all.slice(0,10);\n    if(questions.length<3)throw new Error('لم يتمكن النظام من استخراج أسئلة كافية — جرّب صوراً أوضح');\n    if(lessonTitle && !lname)document.getElementById('lessonName').value=lessonTitle;\n    renderPreview();\n    try{if(window.GHLib)GHLib.save();}catch(_){}\n  }catch(e){\n    showErr('تعذّر توليد الأسئلة: '+e.message+' — جرّب مرة ثانية أو تأكد من وضوح الصور.');\n  }finally{\n    clearInterval(stepInt);\n    document.getElementById('loading').classList.remove('show');\n    document.getElementById('goBtn').disabled=false;\n  }\n}\nfunction showErr(m){const b=document.getElementById('errBox');b.textContent=m;b.classList.add('show')}\nfunction hideErr(){document.getElementById('errBox').classList.remove('show')}\n\nfunction renderPreview(){\n  document.getElementById('qCount').textContent=`(${AR(questions.length)} أسئلة)`;\n  try{saveGame();}catch(_){}\n  document.getElementById('qList').innerHTML=questions.map((q,i)=>\n    `<div class=\"q-item\"><div class=\"qt\">${AR(i+1)}. ${esc(q.q)} <span class=\"lvl\">${q.level||''}</span></div>\n     <div class=\"ans\">✔ ${q.options[q.correct]}</div></div>`).join('');\n  document.getElementById('preview').classList.add('show');\n  try{if(window.QEdit)QEdit.decorate();}catch(_){}\n  try{document.getElementById('preview').scrollIntoView({behavior:'smooth'})}catch(_){}\n}\n\n/* ---------- كتابة الأسئلة يدويًا + الحفظ التلقائي ---------- */\nlet manualQs=[], MANUAL=false;\nconst MLS_KEY='ghiras_millionaire_game_v1';\nfunction addManualQ(){\n  const q=(document.getElementById('mq').value||'').trim();\n  const opts=[0,1,2,3].map(i=>(document.getElementById('mo'+i).value||'').trim());\n  if(!q){showErr('اكتب نص السؤال أولًا');return;}\n  if(opts.some(o=>!o)){showErr('اكتب الخيارات الأربعة كاملة');return;}\n  const cor=+((document.querySelector('input[name=mcorrect]:checked')||{value:'0'}).value);\n  manualQs.push({q,options:opts,correct:cor,level:'',explain:''});\n  document.getElementById('mq').value=''; [0,1,2,3].forEach(i=>document.getElementById('mo'+i).value='');\n  const r0=document.querySelector('input[name=mcorrect][value=\"0\"]'); if(r0)r0.checked=true;\n  hideErr(); renderManList();\n}\nfunction delManualQ(i){ manualQs.splice(i,1); renderManList(); }\nfunction renderManList(){\n  const el=document.getElementById('manList');\n  el.innerHTML=manualQs.map((q,i)=>`<div class=\"man-q\"><div class=\"mqt\">${AR(i+1)}. ${esc(q.q)}<div class=\"mqa\">✔ ${q.options[q.correct]}</div></div><button class=\"mdel\" onclick=\"delManualQ(${i})\">✕</button></div>`).join('');\n  document.getElementById('manUseBtn').style.display=manualQs.length?'block':'none';\n}\nfunction useManual(){\n  if(manualQs.length<1){showErr('أضف سؤالًا واحدًا على الأقل');return;}\n  questions=manualQs.map(q=>({...q,options:[...q.options]}));\n  MANUAL=true; COMMITTED=false;\n  try{saveGame();}catch(_){}\n  renderPreview();\n  try{if(window.GHLib)GHLib.save();}catch(_){}\n}\n/* حفظ/استرجاع اللعبة تلقائيًا */\nfunction saveGame(){try{localStorage.setItem(MLS_KEY,JSON.stringify({questions,lesson:(document.getElementById('lessonName').value||'').trim(),committed:(typeof COMMITTED!=='undefined'&&COMMITTED),manual:(typeof MANUAL!=='undefined'&&MANUAL),ts:Date.now()}));}catch(e){}}\nfunction loadSaved(){try{const r=localStorage.getItem(MLS_KEY);if(!r)return;const d=JSON.parse(r);if(d&&Array.isArray(d.questions)&&d.questions.length){questions=d.questions;if(d.lesson)document.getElementById('lessonName').value=d.lesson;COMMITTED=!!d.committed;MANUAL=!!d.manual;renderPreview();const qc=document.getElementById('qCount');if(qc)qc.textContent=qc.textContent+' — محفوظة ✅';}}catch(e){}}\n\n/* ---------- خطافات مكتبة «ألعابي المحفوظة» (حساب المعلمة) ---------- */\nwindow.__libGetData=function(){\n  if(!questions||!questions.length)return null;\n  const lesson=(document.getElementById('lessonName').value||'').trim();\n  return { title: lesson||'من سيربح المليون',\n           data:{ questions, lesson, manual:(typeof MANUAL!=='undefined'&&MANUAL), committed:(typeof COMMITTED!=='undefined'&&COMMITTED) } };\n};\nwindow.__libApply=function(d){\n  if(!d||!Array.isArray(d.questions))return;\n  questions=d.questions.map(q=>({...q,options:Array.isArray(q.options)?[...q.options]:q.options}));\n  const el=document.getElementById('lessonName'); if(el&&d.lesson)el.value=d.lesson;\n  MANUAL=!!d.manual; COMMITTED=!!d.committed;\n  renderPreview();\n};\n\n/* ---------- محرك الصوت ---------- */\nlet AC=null;\nfunction ac(){if(!AC)AC=new (window.AudioContext||window.webkitAudioContext)();if(AC.state==='suspended')AC.resume();return AC}\nfunction tone(freq,dur,type='sine',vol=.18,when=0,slide=0){\n  try{\n    const c=ac(),o=c.createOscillator(),g=c.createGain();\n    o.type=type;o.frequency.setValueAtTime(freq,c.currentTime+when);\n    if(slide)o.frequency.exponentialRampToValueAtTime(slide,c.currentTime+when+dur);\n    g.gain.setValueAtTime(vol,c.currentTime+when);\n    g.gain.exponentialRampToValueAtTime(.001,c.currentTime+when+dur);\n    o.connect(g);g.connect(c.destination);\n    o.start(c.currentTime+when);o.stop(c.currentTime+when+dur+.05);\n  }catch(_){}\n}\nconst SFX={\n  start(){tone(392,.18,'triangle',.2);tone(523,.18,'triangle',.2,.15);tone(659,.3,'triangle',.22,.3);tone(784,.5,'triangle',.22,.45)},\n  tick(){tone(880,.06,'square',.08)},\n  pick(){tone(440,.12,'sine',.15);tone(330,.25,'sine',.12,.1)},\n  correct(){tone(523,.15,'triangle',.22);tone(659,.15,'triangle',.22,.12);tone(784,.35,'triangle',.24,.24)},\n  wrong(){tone(220,.3,'sawtooth',.16,0,110);tone(180,.4,'sawtooth',.12,.15,90)},\n  win(){[523,659,784,1047,784,1047,1319].forEach((f,i)=>tone(f,.22,'triangle',.2,i*.14))},\n  next(){tone(587,.1,'sine',.12);tone(740,.15,'sine',.12,.08)}\n};\n\nfunction demoPlay(){\n  questions=[\n    {q:'ما المراحل التي يمر بها الإنسان بالترتيب الصحيح؟',options:['الحياة الدنيا ثم الموت ثم البعث ثم الحشر ثم الحساب','الموت ثم الحياة الدنيا ثم الحساب','الحشر ثم البعث ثم الموت','الحساب ثم الحياة الدنيا ثم البعث'],correct:0,level:'تذكر',explain:'يمر الإنسان بالحياة الدنيا ثم الموت ثم البعث ثم الحشر ثم الحساب.'},\n    {q:'ما معنى البعث؟',options:['إخراج الناس من قبورهم أحياء يوم القيامة','جمع الناس في أرض واحدة','نهاية الحياة الدنيا','محاسبة الناس على أعمالهم'],correct:0,level:'فهم',explain:'البعث هو إحياء الله للناس وإخراجهم من قبورهم يوم القيامة.'},\n    {q:'ما الأرض التي يُحشر إليها الناس؟',options:['أرض الشام','أرض مكة','أرض المدينة','أرض مصر'],correct:0,level:'تذكر',explain:'الشام هي أرض المحشر والمنشر كما ورد في الدرس.'},\n    {q:'ما حكم الإيمان بالبعث والحشر؟',options:['واجب وركن من أركان الإيمان','مستحب','مباح','سنة'],correct:0,level:'فهم',explain:'الإيمان بالبعث والحشر واجب، وهو داخل في الإيمان باليوم الآخر أحد أركان الإيمان.'},\n    {q:'ما معنى الحشر؟',options:['جمع الناس في أرض واحدة للحساب','خروج الناس من قبورهم','دخول الجنة','الحياة في الدنيا'],correct:0,level:'فهم',explain:'الحشر هو جمع الله الخلائق في أرض واحدة يوم القيامة للحساب.'},\n    {q:'ماذا يأتي بعد الحشر مباشرة؟',options:['الحساب','الموت','الحياة الدنيا','البعث'],correct:0,level:'تطبيق',explain:'بعد أن يُحشر الناس يقفون بين يدي الله للحساب على أعمالهم.'},\n    {q:'من أول من تنشقّ عنه الأرض يوم القيامة؟',options:['النبي محمد ﷺ','آدم عليه السلام','نوح عليه السلام','موسى عليه السلام'],correct:0,level:'تذكر',explain:'ورد أن النبي محمداً ﷺ أول من تنشقّ عنه الأرض يوم القيامة.'},\n    {q:'ما الحال التي يُبعث عليها الناس يوم القيامة؟',options:['حفاة عراة غير مختونين','بكامل ثيابهم','راكبين','نائمين'],correct:0,level:'فهم',explain:'يُبعث الناس حفاة عراة غُرلاً كما جاء في الحديث.'},\n    {q:'لماذا خلق الله الخلق ثم يبعثهم؟',options:['ليجازيهم على أعمالهم','عبثاً بلا هدف','ليتركهم','ليعذّبهم فقط'],correct:0,level:'تطبيق',explain:'البعث ليجازي الله كل نفس بما كسبت، فلا يضيع عمل.'},\n    {q:'ما موقف المؤمن من يوم البعث؟',options:['يستعدّ له بالعمل الصالح','يخاف ولا يعمل','ينكره','ينساه'],correct:0,level:'تقويم',explain:'المؤمن يوقن بالبعث فيستعدّ له بالأعمال الصالحة.'}\n  ];\n  document.getElementById('lessonName').value=document.getElementById('lessonName').value.trim()||'البعث والحشر';\n  DEMO=true;COMMITTED=false;MANUAL=false;openGame();\n}\n\nlet AC2_unused;\nlet slotFailed={};\nasync function openGame(){\n  if(!DEMO && !COMMITTED){\n    const _c=await consumeCredit();\n    if(!_c.ok){ showBuy(); return; }\n    COMMITTED=true;\n    if(!_c.unlimited && typeof _c.remaining==='number'){ CREDITS=_c.remaining; }\n    updateCreditBadge();\n    try{saveGame();}catch(_){}\n    try{if(window.GHLib){GHLib.commitSave();}}catch(_){}\n  }\n  gi=0;correct=0;helpsUsed={fifty:false,teacher:false,audience:false};slotFailed={};\n  /* خلط مواقع الإجابات عشوائياً */\n  questions=questions.map(q=>{\n    const idx=[0,1,2,3].sort(()=>Math.random()-.5);\n    return {...q,options:idx.map(i=>q.options[i]),correct:idx.indexOf(q.correct)};\n  });\n  questions=questions.slice(0,10);\n  LADDER=getLadder(questions.length);\n  document.getElementById('game').classList.add('show');\n  document.body.style.overflow='hidden';\n  const lname=document.getElementById('lessonName').value.trim()||'مراجعة الدرس';\n  LESSON=lname;\n  document.getElementById('gInner').innerHTML=`\n    <div class=\"g-start\">\n      <div class=\"g-logo\"><b>من سيربح<span>المليون</span></b></div>\n      <div class=\"g-title hexline hex\"><div class=\"hexin hex\">${lname}</div></div>\n      <h2>اختر الإجابة الصحيحة واربح أعلى مبلغ!</h2>\n      <input id=\"pName\" placeholder=\"اكتب اسمك هنا\">\n      <button class=\"g-startbtn\" onclick=\"startPlay()\">ابدأ التحدي 🚀</button>\n      <div style=\"display:flex;align-items:center;justify-content:center;gap:14px;margin-top:26px\">\n        <span style=\"font-size:44px\">🏆</span>\n        <div style=\"background:#EAF3FF;color:#123A8C;font-weight:900;font-size:14px;line-height:1.7;padding:14px 20px;border-radius:24px;position:relative;max-width:230px;box-shadow:0 4px 12px rgba(0,0,0,.3)\">\n          أنت ذكي .. فكر جيداً<br>والإجابة الصحيحة قريبة منك !\n          <span style=\"position:absolute;right:-8px;top:50%;width:0;height:0;border:10px solid transparent;border-left-color:#EAF3FF\"></span>\n        </div>\n        <span style=\"font-size:34px\">💡</span>\n      </div>\n    </div>\n    <div class=\"g-brand\">🌱 غراس المعلم — جميع الحقوق محفوظة</div>`;\n}\nfunction closeGame(){clearInterval(timerInt);document.getElementById('game').classList.remove('show');document.body.style.overflow=''}\nfunction startPlay(){playerName=document.getElementById('pName').value.trim()||'البطل';SFX.start();showQ()}\n\nfunction showQ(){\n  if(gi>=questions.length)return endGame();\n  const q=questions[gi];timeLeft=30;\n  const ladder=[...LADDER].map((p,i)=>({p,i})).reverse().map(({p,i})=>{\n    const cur=i===gi;\n    return `<div class=\"lrow ${cur?'cur':i<gi?'won':''}\">\n      <span class=\"li\">${AR(i+1)}</span><span class=\"lp\">${p}</span>\n      <span class=\"lc\">${cur?'◆':i>gi?'🟡':'✓'}</span></div>`}).join('');\n  document.getElementById('gInner').innerHTML=`\n    <div class=\"q-header\"><div class=\"q-title\"><span>${LESSON||'مراجعة الدرس'}</span></div><div class=\"q-sub2\">اختر الإجابة الصحيحة</div></div>\n    <div class=\"hud\">\n      <span class=\"pill\">السؤال ${AR(gi+1)} من ${AR(questions.length)}</span>\n      <span class=\"pill\" id=\"timer\">⏱ ${AR(timeLeft)}</span>\n    </div>\n    <div class=\"prog\"><i style=\"width:${(gi/questions.length)*100}%\"></i></div>\n    <div class=\"play-grid\">\n      <div>\n        <div class=\"q-box\">\n          <div class=\"q-label\"><span>السؤال ${AR(gi+1)}</span></div>\n          <div class=\"hexline hex\"><div class=\"hexin hex\">${esc(q.q)}</div></div>\n        </div>\n        <div class=\"opts\" id=\"opts\">${q.options.map((o,i)=>\n          `<button class=\"opt\" data-i=\"${i}\" onclick=\"answer(${i})\"><span class=\"n\">${AR(i+1)}</span><span class=\"hexline hex\"><span class=\"hexin hex\">${esc(o)}</span></span></button>`).join('')}</div>\n        <div class=\"fb\" id=\"fb\"></div>\n      </div>\n      <div class=\"ladder-col\">\n        <div class=\"g-logo\" style=\"width:104px;height:104px;margin:0 auto 12px\"><b style=\"font-size:14px\">من سيربح<span style=\"font-size:20px\">المليون</span></b></div>\n        <div class=\"ladder\">\n        <h3>قائمة المبالغ</h3>\n        ${ladder}\n        <div class=\"helps\">\n          <button class=\"help\" id=\"hFifty\" ${helpsUsed.fifty?'disabled':''} onclick=\"useFifty()\">50:50</button>\n          <button class=\"help\" id=\"hTeacher\" ${helpsUsed.teacher?'disabled':''} onclick=\"useTeacher()\">📞</button>\n          <button class=\"help\" id=\"hAud\" ${helpsUsed.audience?'disabled':''} onclick=\"useAudience()\">👥</button>\n        </div>\n      </div>\n      </div>\n    </div>\n    <div class=\"g-brand\">🌱 غراس المعلم</div>`;\n  clearInterval(timerInt);\n  timerInt=setInterval(()=>{\n    timeLeft--;const t=document.getElementById('timer');\n    if(!t){clearInterval(timerInt);return}\n    t.textContent='⏱ '+AR(Math.max(timeLeft,0));\n    if(timeLeft<=10){t.classList.add('hot');SFX.tick()}\n    if(timeLeft<=0){clearInterval(timerInt);answer(-1)}\n  },1000);\n}\n\nfunction answer(i){\n  clearInterval(timerInt);\n  const q=questions[gi];\n  document.querySelectorAll('.opt').forEach(b=>b.disabled=true);\n  const ok=i===q.correct;\n  SFX.pick();\n  if(ok){\n    if(!slotFailed[gi])correct++;\n    setTimeout(()=>SFX.correct(),350);\n    document.querySelector(`.opt[data-i=\"${i}\"]`).classList.add('correct');\n  }else{\n    slotFailed[gi]=true;\n    setTimeout(()=>SFX.wrong(),350);\n    if(i>=0)document.querySelector(`.opt[data-i=\"${i}\"]`)?.classList.add('wrong');\n    document.querySelector(`.opt[data-i=\"${q.correct}\"]`).classList.add('correct');\n  }\n  const fb=document.getElementById('fb');\n  fb.innerHTML=`<div class=\"h ${ok?'ok':'no'}\">${ok?'✔️ أحسنت! إجابة صحيحة':(i<0?'⏱ انتهى الوقت!':'❌ إجابة غير صحيحة')}</div>\n    ${!ok?`<div class=\"ex\" style=\"font-weight:800;color:#F3C64B\">الإجابة الصحيحة: ${q.options[q.correct]}</div>`:''}\n    <div class=\"ex\">${esc(q.explain||'')}</div>\n    ${ok\n      ?`<button onclick=\"SFX.next();gi++;showQ()\">${gi+1>=questions.length?'عرض النتيجة 🏆':'السؤال التالي ➡️'}</button>`\n      :`<button onclick=\"SFX.next();swapQuestion()\">سؤال جديد 🔄</button>`}`;\n  fb.classList.add('show');\n  try{fb.scrollIntoView({behavior:'smooth',block:'nearest'})}catch(_){}\n}\n\n/* استبدال السؤال الحالي بسؤال آخر لم يُعرض بعد — نفس مستوى الجائزة */\nfunction swapQuestion(){\n  const cur=questions.splice(gi,1)[0];\n  /* إصلاح تعلّق السؤال الأخير: إن كنّا عند آخر سؤال أدخله أوّل القائمة حتى يظهر سؤال مختلف بنفس مستوى الجائزة (gi لا يتغيّر) */\n  if(gi>=questions.length){ questions.unshift(cur); } else { questions.push(cur); }\n  showQ();\n}\n\n/* ---------- وسائل المساعدة ---------- */\nfunction useFifty(){\n  helpsUsed.fifty=true;document.getElementById('hFifty').disabled=true;\n  const q=questions[gi];\n  const wrong=[0,1,2,3].filter(i=>i!==q.correct).sort(()=>Math.random()-.5).slice(0,2);\n  wrong.forEach(i=>document.querySelector(`.opt[data-i=\"${i}\"]`).classList.add('dim'));\n}\nfunction useTeacher(){\n  helpsUsed.teacher=true;document.getElementById('hTeacher').disabled=true;\n  const q=questions[gi];\n  alert('📞 المعلم يقول: فكر جيداً… أعتقد أن الإجابة هي: '+q.options[q.correct]);\n}\nfunction useAudience(){\n  helpsUsed.audience=true;document.getElementById('hAud').disabled=true;\n  const q=questions[gi];\n  let pct=[0,0,0,0],rem=100;\n  pct[q.correct]=55+Math.floor(Math.random()*20);rem-=pct[q.correct];\n  [0,1,2,3].filter(i=>i!==q.correct).forEach((i,x,arr)=>{\n    const v=x===arr.length-1?rem:Math.floor(Math.random()*rem);pct[i]=v;rem-=v;\n  });\n  alert('👥 تصويت الجمهور:\\n'+pct.map((p,i)=>'①②③④'[i]+' — '+AR(p)+'٪').join('\\n'));\n}\n\n/* ---------- النهاية ---------- */\nfunction endGame(){\n  const pct=Math.round((correct/questions.length)*100);\n  const medal=pct>=90?'🥇':pct>=70?'🥈':pct>=50?'🥉':'🌟';\n  const medalTxt=pct>=90?'الوسام الذهبي':pct>=70?'الوسام الفضي':pct>=50?'الوسام البرونزي':'وسام المحاولة';\n  const prize=correct>0?LADDER[Math.min(correct-1,LADDER.length-1)]:'٠';\n  document.getElementById('gInner').innerHTML=`\n    <div class=\"g-end\">\n      <div class=\"g-logo\" style=\"width:90px;height:90px;margin-bottom:6px\"><b style=\"font-size:13px\">من سيربح<span style=\"font-size:18px\">المليون</span></b></div>\n      <div class=\"medal\">${medal}</div>\n      <h1>🎉 تهانينا يا ${esc(playerName)}!</h1>\n      <p style=\"color:#B9C4EF;font-weight:700\">${medalTxt}</p>\n      <div class=\"stats\">\n        <div class=\"st\"><b>${AR(correct)}/${AR(questions.length)}</b><span>إجابات صحيحة</span></div>\n        <div class=\"st\"><b>${AR(pct)}٪</b><span>النسبة</span></div>\n        <div class=\"st\"><b>${prize}</b><span>الجائزة</span></div>\n      </div>\n      <button class=\"g-startbtn\" onclick=\"openGame()\">🔄 العب مرة أخرى</button>\n      <button class=\"help\" style=\"margin-top:14px\" onclick=\"window.print()\">📄 طباعة النتيجة</button>\n      <button class=\"help\" style=\"margin-top:8px\" onclick=\"closeGame()\">🌱 العودة للمولّد</button>\n    </div>\n    <div class=\"g-brand\">🌱 غراس المعلم — جميع الحقوق محفوظة</div>`;\n  if(pct>=50){confetti();SFX.win()}else{SFX.next()}\n}\nfunction confetti(){\n  const colors=['#F3C64B','#7A9E7E','#FF7B6B','#5DADE2','#C084D4'];\n  for(let i=0;i<80;i++){\n    const c=document.createElement('div');c.className='confetti';\n    c.style.cssText=`left:${Math.random()*100}vw;background:${colors[i%5]};animation-duration:${2+Math.random()*2.5}s;animation-delay:${Math.random()*1.2}s`;\n    document.body.appendChild(c);setTimeout(()=>c.remove(),5000);\n  }\n}\nwindow.addEventListener('load',()=>{try{loadSaved();}catch(_){}});\n\n/* ---------- نظام رصيد الألعاب ---------- */\nasync function consumeCredit(){\n  if(IS_ADMIN) return {ok:true,unlimited:true};\n  try{\n    const r=await fetch('/api/game-consume',{method:'POST'});\n    const d=await r.json();\n    if(!d.ok) return {ok:false,error:d.error};\n    return {ok:true,remaining:d.remaining,unlimited:d.unlimited};\n  }catch(_){ return {ok:false,error:'net'}; }\n}\nfunction updateCreditBadge(){\n  const el=document.getElementById('creditBadge');\n  if(!el)return;\n  if(IS_ADMIN){ el.innerHTML='♾️ رصيد غير محدود'; el.className='cbadge admin'; return; }\n  el.innerHTML='🎟️ رصيدك: <b>'+AR(CREDITS)+'</b> '+(CREDITS===1?'لعبة':'ألعاب');\n  el.className='cbadge'+(CREDITS<=0?' empty':'');\n  try{var _fb=document.getElementById('freeBanner'); if(_fb)_fb.style.display=(!IS_ADMIN && CREDITS===1)?'block':'none';}catch(e){}\n}\nfunction showBuy(){\n  let m=document.getElementById('buyModal');\n  if(!m){\n    m=document.createElement('div'); m.id='buyModal'; m.className='buy-ov';\n    m.innerHTML=`<div class=\"buy-card\">\n      <button class=\"buy-x\" onclick=\"closeBuy()\">✕</button>\n      <div class=\"buy-seed\">🎟️</div>\n      <h3>خلص رصيد الألعاب</h3>\n      <p>لإنشاء لعبة جديدة من درسك، اختر باقة الرصيد المناسبة:</p>\n      <div class=\"buy-opts\">\n        <button class=\"buy-opt\" onclick=\"buyGame(1)\">\n          <b>لعبة واحدة</b><span class=\"pr\">٢ د.ك</span>\n        </button>\n        <button class=\"buy-opt best\" onclick=\"buyGame(5)\">\n          <span class=\"tag\">الأوفر</span>\n          <b>٥ ألعاب</b><span class=\"pr\">٨ د.ك</span><small>١.٦ د.ك للعبة</small>\n        </button>\n      </div>\n      <p class=\"buy-note\">التفعيل حالياً عبر إدارة غراس المعلم، والدفع الإلكتروني المباشر قريباً 🌱</p>\n    </div>`;\n    document.body.appendChild(m);\n  }\n  m.classList.add('show');\n}\nfunction closeBuy(){ const m=document.getElementById('buyModal'); if(m)m.classList.remove('show'); }\nfunction buyGame(n){\n  closeBuy();\n  alert(n===1\n    ? '🎟️ لشراء لعبة واحدة (٢ د.ك): يرجى التواصل مع إدارة غراس المعلم لتفعيل الرصيد.\\nوقريباً يصير الدفع مباشرة داخل التطبيق.'\n    : '🎟️ لشراء باقة ٥ ألعاب (٨ د.ك): يرجى التواصل مع إدارة غراس المعلم لتفعيل الرصيد.\\nوقريباً يصير الدفع مباشرة داخل التطبيق.');\n}\ntry{ updateCreditBadge(); }catch(_){}\n\n\n/* ===== مكتبة ألعابي المحفوظة ===== */\n\n/* ===================== GHIRAS-LIBRARY : ألعابي المحفوظة ===================== */\n(function(){\n  const TYPE='millionaire';               // نوع اللعبة (يُستبدل عند البناء)\n  const LABEL='من سيربح المليون';             // اسم اللعبة للعرض\n  const API='/api/saved-games';\n  const arNum=(n)=>String(n).replace(/[0-9]/g,d=>'٠١٢٣٤٥٦٧٨٩'[d]);\n  window.__libCurId = window.__libCurId || null;\n\n  // ---------- بناء الواجهة ----------\n  const css=`\n  #libFab{position:fixed;bottom:18px;inset-inline-start:18px;z-index:900;display:inline-flex;align-items:center;gap:8px;\n    background:linear-gradient(180deg,#FFE9A8,#F0C24C);color:#5A3E00;font-weight:800;font-size:.95rem;font-family:inherit;\n    padding:12px 18px;border:none;border-radius:999px;box-shadow:0 8px 22px rgba(217,162,22,.4);cursor:pointer;transition:transform .15s}\n  #libFab:hover{transform:translateY(-2px) scale(1.03)}\n  #libFab .cnt{background:#fff;color:#B98900;border-radius:999px;min-width:22px;height:22px;display:inline-flex;align-items:center;justify-content:center;font-size:.8rem;padding:0 6px}\n  #libBg{position:fixed;inset:0;background:rgba(18,24,40,.55);z-index:950;display:none;align-items:center;justify-content:center;padding:18px;backdrop-filter:blur(3px)}\n  #libBg.on{display:flex}\n  #libCard{background:#fff;border-radius:24px;max-width:560px;width:100%;max-height:82vh;display:flex;flex-direction:column;box-shadow:0 24px 60px rgba(0,0,0,.35);overflow:hidden;font-family:inherit;direction:rtl}\n  #libHead{background:linear-gradient(180deg,#FFF6DC,#FDE9B8);padding:18px 20px;display:flex;align-items:center;justify-content:space-between}\n  #libHead h3{margin:0;color:#5A3E00;font-size:1.15rem;font-weight:800}\n  #libHead .x{background:#fff;border:none;width:34px;height:34px;border-radius:50%;font-size:1.1rem;cursor:pointer;color:#8a6d1e;box-shadow:0 3px 8px rgba(0,0,0,.12)}\n  #libBody{padding:16px 18px;overflow:auto}\n  .libItem{display:flex;align-items:center;gap:12px;background:#F8FAFF;border:1.5px solid #E7EDF5;border-radius:16px;padding:12px 14px;margin-bottom:10px}\n  .libItem .ic{font-size:1.6rem}\n  .libItem .mid{flex:1;min-width:0}\n  .libItem .t{font-weight:800;color:#22314B;font-size:1rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n  .libItem .s{font-size:.78rem;color:#8794A6;font-weight:700;margin-top:2px}\n  .libItem .op{background:linear-gradient(180deg,#7FD79A,#49B96E);color:#fff;border:none;font-weight:800;font-family:inherit;\n    padding:9px 16px;border-radius:12px;cursor:pointer;font-size:.9rem;white-space:nowrap}\n  .libItem .dl{background:#fff;border:1.5px solid #F2C4C4;color:#D45B5B;width:38px;height:38px;border-radius:12px;cursor:pointer;font-size:1rem}\n  .libEmpty{text-align:center;color:#8794A6;font-weight:700;padding:34px 10px;line-height:1.9}\n  .libToast{position:fixed;bottom:78px;inset-inline-start:18px;z-index:980;background:#2E7D46;color:#fff;font-weight:800;\n    font-family:inherit;padding:11px 18px;border-radius:14px;box-shadow:0 8px 20px rgba(0,0,0,.25);opacity:0;transform:translateY(8px);transition:all .25s}\n  .libToast.on{opacity:1;transform:translateY(0)}\n  @media(max-width:520px){#libFab span.tx{display:none}}\n  `;\n  const st=document.createElement('style'); st.textContent=css; document.head.appendChild(st);\n\n  const fab=document.createElement('button'); fab.id='libFab';\n  fab.innerHTML=`📚 <span class=\"tx\">ألعابي المحفوظة</span> <span class=\"cnt\" id=\"libCnt\">٠</span>`;\n  fab.onclick=open;\n  const bg=document.createElement('div'); bg.id='libBg';\n  bg.innerHTML=`<div id=\"libCard\">\n     <div id=\"libHead\"><h3>📚 ألعابي المحفوظة — ${LABEL}</h3><button class=\"x\" onclick=\"GHLib.close()\">✕</button></div>\n     <div id=\"libBody\"><div class=\"libEmpty\">جارِ التحميل…</div></div>\n   </div>`;\n  bg.addEventListener('click',e=>{ if(e.target===bg) close(); });\n  function mount(){ if(!document.body){ return setTimeout(mount,50); } document.body.appendChild(fab); document.body.appendChild(bg); refreshCount(); }\n  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',mount); else mount();\n\n  // ---------- شبكة ----------\n  async function jget(u){ const r=await fetch(u); if(!r.ok) throw new Error('http'); return r.json(); }\n  async function listGames(){ try{ const d=await jget(API+'?type='+TYPE); return d.games||[]; }catch(e){ return null; } }\n\n  let cache=[];\n  async function refreshCount(){ const g=await listGames(); if(g===null)return; cache=g; const c=document.getElementById('libCnt'); if(c)c.textContent=arNum(g.length); }\n\n  function open(){ bg.classList.add('on'); render(); }\n  function close(){ bg.classList.remove('on'); }\n\n  async function render(){\n    const body=document.getElementById('libBody');\n    body.innerHTML=`<div class=\"libEmpty\">جارِ التحميل…</div>`;\n    const g=await listGames();\n    if(g===null){ body.innerHTML=`<div class=\"libEmpty\">تعذّر الاتصال. تأكد من تسجيل الدخول وحاول مرة أخرى.</div>`; return; }\n    cache=g;\n    const c=document.getElementById('libCnt'); if(c)c.textContent=arNum(g.length);\n    if(!g.length){ body.innerHTML=`<div class=\"libEmpty\">ما عندك ألعاب محفوظة بعد 🌱<br>أنشئ لعبة وبتنحفظ هنا تلقائيًا لترجع لها أي وقت.</div>`; return; }\n    body.innerHTML=g.map(it=>{\n      const dt=fmt(it.updated_at);\n      return `<div class=\"libItem\" data-id=\"${it.id}\">\n        <span class=\"ic\">${icon()}</span>\n        <div class=\"mid\"><div class=\"t\">${esc(it.title||'لعبة')}</div><div class=\"s\">آخر تحديث: ${dt}</div></div>\n        <button class=\"op\" onclick=\"GHLib.load('${it.id}')\">▶️ افتح</button>\n        <button class=\"dl\" title=\"حذف\" onclick=\"GHLib.del('${it.id}',event)\">🗑️</button>\n      </div>`;\n    }).join('');\n  }\n\n  function icon(){ return ({millionaire:'🏆',snake:'🎲',xo:'⭕',sinjim:'🧠'})[TYPE]||'🎮'; }\n  function esc(s){ return String(s).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c])); }\n  function fmt(iso){ try{ const d=new Date(iso); const D=arNum(d.getDate()), M=arNum(d.getMonth()+1), Y=arNum(d.getFullYear()); return `${D}/${M}/${Y}`; }catch(e){ return '—'; } }\n\n  function toast(msg){ const t=document.createElement('div'); t.className='libToast'; t.textContent=msg; document.body.appendChild(t);\n    requestAnimationFrame(()=>t.classList.add('on')); setTimeout(()=>{t.classList.remove('on'); setTimeout(()=>t.remove(),300);},2200); }\n\n  // ---------- حفظ تلقائي ----------\n  function newGame(){ window.__libCurId=null; }  // يُستدعى عند إنشاء لعبة جديدة\n\n  async function save(){\n    if(typeof window.__libGetData!=='function') return;\n    const g=window.__libGetData(); if(!g||!g.data) return;\n    try{\n      const r=await fetch(API,{method:'POST',headers:{'Content-Type':'application/json'},\n        body:JSON.stringify({id:window.__libCurId||undefined, game_type:TYPE, title:g.title||'لعبة', data:g.data})});\n      const d=await r.json(); if(d&&d.id){ window.__libCurId=d.id; refreshCount(); }\n    }catch(e){}\n  }\n\n  // حفظ عند اللعب ثم بدء لعبة جديدة (يمنع الكتابة فوق اللعبة المدفوعة)\n  async function commitSave(){ await save(); newGame(); }\n\n  async function load(id){\n    const it=cache.find(x=>x.id===id); if(!it) return;\n    if(typeof window.__libApply==='function'){ try{ window.__libApply(it.data); }catch(e){} }\n    window.__libCurId=id; close(); toast('✅ فُتحت اللعبة — جاهزة للّعب');\n  }\n\n  async function del(id,ev){ if(ev)ev.stopPropagation();\n    try{ await fetch(API+'?id='+encodeURIComponent(id),{method:'DELETE'}); }catch(e){}\n    cache=cache.filter(x=>x.id!==id); render(); refreshCount();\n  }\n\n  window.GHLib={open,close,load,del,save,newGame,commitSave,refreshCount};\n})();\n\n\n/* ===== تعديل الأسئلة ===== */\n\n/* ===================== GHIRAS-QEDIT : تعديل الأسئلة بعد التوليد ===================== */\n(function(){\n  const arNum=(n)=>String(n).replace(/[0-9]/g,d=>'٠١٢٣٤٥٦٧٨٩'[d]);\n\n  const css=`\n  .qedit-btn{margin-top:8px;display:inline-flex;align-items:center;gap:5px;background:#EEF3FF;border:1.5px solid #C9D8F2;\n    color:#2C4A78;font-weight:800;font-family:inherit;font-size:.82rem;padding:6px 12px;border-radius:10px;cursor:pointer;transition:.15s}\n  .qedit-btn:hover{background:#E1EBFC;border-color:#A9C4EC}\n  #qeBg{position:fixed;inset:0;background:rgba(18,24,40,.55);z-index:960;display:none;align-items:center;justify-content:center;padding:18px;backdrop-filter:blur(3px)}\n  #qeBg.on{display:flex}\n  #qeCard{background:#fff;border-radius:22px;max-width:560px;width:100%;max-height:88vh;display:flex;flex-direction:column;\n    box-shadow:0 24px 60px rgba(0,0,0,.35);overflow:hidden;font-family:inherit;direction:rtl}\n  #qeHead{background:linear-gradient(180deg,#EAF1FF,#D8E6FB);padding:16px 20px;display:flex;align-items:center;justify-content:space-between}\n  #qeHead h3{margin:0;color:#26426E;font-size:1.1rem;font-weight:800}\n  #qeHead .x{background:#fff;border:none;width:32px;height:32px;border-radius:50%;font-size:1rem;cursor:pointer;color:#5b6b86;box-shadow:0 3px 8px rgba(0,0,0,.12)}\n  #qeBody{padding:18px 20px;overflow:auto}\n  .qe-lbl{font-weight:800;color:#33465F;font-size:.9rem;margin:0 0 6px}\n  #qeQ{width:100%;box-sizing:border-box;padding:12px 14px;border-radius:14px;border:2px solid #DDE6F0;font-family:inherit;\n    font-size:1.02rem;font-weight:700;color:#22314B;background:#F8FBFF;resize:vertical;min-height:64px;line-height:1.7}\n  #qeQ:focus{outline:none;border-color:#7FA8E0;background:#fff}\n  .qe-opt{display:flex;align-items:center;gap:10px;margin-bottom:10px}\n  .qe-opt input[type=radio]{width:22px;height:22px;accent-color:#2E7D46;flex:none;cursor:pointer}\n  .qe-opt input[type=text]{flex:1;padding:11px 13px;border-radius:12px;border:2px solid #DDE6F0;font-family:inherit;\n    font-size:1rem;font-weight:700;color:#22314B;background:#F8FBFF}\n  .qe-opt input[type=text]:focus{outline:none;border-color:#7FA8E0;background:#fff}\n  .qe-hint{font-size:.8rem;color:#8794A6;font-weight:700;margin:2px 0 14px}\n  .qe-actions{display:flex;gap:10px;justify-content:flex-start;flex-wrap:wrap;margin-top:6px}\n  .qe-save{background:linear-gradient(180deg,#7FD79A,#49B96E);color:#fff;border:none;font-weight:800;font-family:inherit;\n    padding:12px 24px;border-radius:14px;cursor:pointer;font-size:1rem}\n  .qe-cancel{background:#fff;border:2px solid #DDE6F0;color:#4A5A72;font-weight:800;font-family:inherit;padding:11px 20px;border-radius:14px;cursor:pointer}\n  .qe-err{color:#C0392B;font-weight:800;font-size:.85rem;margin-top:8px;min-height:18px}\n  .qeToast{position:fixed;bottom:20px;inset-inline-start:18px;z-index:980;background:#2E7D46;color:#fff;font-weight:800;\n    font-family:inherit;padding:11px 18px;border-radius:14px;box-shadow:0 8px 20px rgba(0,0,0,.25);opacity:0;transform:translateY(8px);transition:all .25s}\n  .qeToast.on{opacity:1;transform:translateY(0)}\n  `;\n  const st=document.createElement('style'); st.textContent=css; document.head.appendChild(st);\n\n  const bg=document.createElement('div'); bg.id='qeBg';\n  bg.innerHTML=`<div id=\"qeCard\">\n    <div id=\"qeHead\"><h3>✏️ تعديل السؤال</h3><button class=\"x\" onclick=\"QEdit.close()\">✕</button></div>\n    <div id=\"qeBody\"></div></div>`;\n  bg.addEventListener('click',e=>{ if(e.target===bg) close(); });\n  function mount(){ if(!document.body)return setTimeout(mount,50); document.body.appendChild(bg); }\n  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',mount); else mount();\n\n  let curIdx=-1;\n\n  function qArr(){ try{ return questions; }catch(e){ return (window.questions||[]); } }\n\n  function decorate(){\n    const list=document.getElementById('qList'); if(!list)return;\n    const items=list.querySelectorAll('.q-item');\n    items.forEach((it,gi)=>{\n      if(it.querySelector('.qedit-btn'))return;\n      const b=document.createElement('button'); b.type='button'; b.className='qedit-btn'; b.textContent='✏️ تعديل';\n      b.onclick=(e)=>{ e.stopPropagation(); open(gi); };\n      it.appendChild(b);\n    });\n  }\n\n  function open(i){\n    const arr=qArr(); const q=arr[i]; if(!q)return; curIdx=i;\n    const opts=Array.isArray(q.options)?q.options:[];\n    const body=document.getElementById('qeBody');\n    body.innerHTML=`\n      <div class=\"qe-lbl\">نص السؤال</div>\n      <textarea id=\"qeQ\">${esc(q.q||'')}</textarea>\n      <div style=\"height:14px\"></div>\n      <div class=\"qe-lbl\">الخيارات — اختر الإجابة الصحيحة 👆</div>\n      <div class=\"qe-hint\">علّم الدائرة بجانب الإجابة الصحيحة</div>\n      ${opts.map((o,j)=>`<div class=\"qe-opt\">\n        <input type=\"radio\" name=\"qeCorrect\" value=\"${j}\" ${j===q.correct?'checked':''} title=\"الإجابة الصحيحة\">\n        <input type=\"text\" id=\"qeO${j}\" value=\"${esc(o)}\" placeholder=\"الخيار ${arNum(j+1)}\">\n      </div>`).join('')}\n      <div class=\"qe-err\" id=\"qeErr\"></div>\n      <div class=\"qe-actions\">\n        <button class=\"qe-save\" onclick=\"QEdit.save()\">💾 حفظ التعديل</button>\n        <button class=\"qe-cancel\" onclick=\"QEdit.close()\">إلغاء</button>\n      </div>`;\n    bg.classList.add('on');\n    setTimeout(()=>{ const t=document.getElementById('qeQ'); if(t)t.focus(); },60);\n  }\n\n  function save(){\n    const arr=qArr(); const q=arr[curIdx]; if(!q)return close();\n    const qt=(document.getElementById('qeQ').value||'').trim();\n    const n=(Array.isArray(q.options)?q.options:[]).length;\n    const opts=[]; for(let j=0;j<n;j++){ opts.push((document.getElementById('qeO'+j).value||'').trim()); }\n    const cor=+((document.querySelector('input[name=qeCorrect]:checked')||{value:'0'}).value);\n    const err=document.getElementById('qeErr');\n    if(!qt){ err.textContent='اكتب نص السؤال'; return; }\n    if(opts.some(o=>!o)){ err.textContent='املأ كل الخيارات'; return; }\n    // تعديل في المكان (يحافظ على الربط مع الفئات في سين جيم)\n    q.q=qt; q.options=opts; q.correct=cor;\n    close();\n    try{ renderPreview(); }catch(_){}\n    try{ if(window.GHLib) GHLib.save(); }catch(_){}\n    toast('✅ تم حفظ التعديل');\n  }\n\n  function close(){ bg.classList.remove('on'); curIdx=-1; }\n  function esc(s){ return String(s).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c])); }\n  function toast(m){ const t=document.createElement('div'); t.className='qeToast'; t.textContent=m; document.body.appendChild(t);\n    requestAnimationFrame(()=>t.classList.add('on')); setTimeout(()=>{t.classList.remove('on'); setTimeout(()=>t.remove(),300);},2000); }\n\n  window.QEdit={decorate,open,save,close};\n})();\n";

export default async function MillionairePage() {
  const supabase = createServerSupabase();
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) redirect('/login?next=/millionaire');

  const { data: profile } = await supabase
    .from('profiles')
    .select('role, status, game_credits, interactive_games_until')
    .eq('id', user.id)
    .single();

  const isAdmin = profile?.role === 'admin';
  const credits = profile?.game_credits ?? 0;
  if (!isAdmin && profile?.status === 'suspended') redirect('/');
  const igu = (profile as { interactive_games_until?: string | null } | null)?.interactive_games_until ?? null;
  if (!isAdmin && !(igu && new Date(igu) > new Date())) redirect('/games-locked');

  const boot = `window.__IS_ADMIN=${isAdmin ? 'true' : 'false'};window.__GAME_CREDITS=${isAdmin ? 9999 : credits};`;

  return (
    <>
      <a href="/games" id="ghiras-back-btn" style={{position:'fixed',top:10,left:10,zIndex:2147483647,display:'flex',alignItems:'center',gap:6,background:'rgba(65,96,63,.92)',color:'#fff',fontFamily:"Cairo,'Segoe UI',sans-serif",fontWeight:800,fontSize:13,lineHeight:1,padding:'9px 14px',borderRadius:999,textDecoration:'none',boxShadow:'0 4px 14px rgba(0,0,0,.28)'}}>← ألعاب غراس</a>
      <style dangerouslySetInnerHTML={{ __html: GAME_CSS }} />
      <div dangerouslySetInnerHTML={{ __html: GAME_BODY }} />
      <Script id="mg-boot" strategy="afterInteractive" dangerouslySetInnerHTML={{ __html: boot }} />
      <Script id="mg-main" strategy="afterInteractive" dangerouslySetInnerHTML={{ __html: GAME_JS }} />
    </>
  );
}
